def lcs(s1, s2):
    m, n = len(s1), len(s2)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i-1] == s2[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])
    return dp[m][n]

def lcs_space_optimized(s1, s2):
    if len(s1) < len(s2):
        s1, s2 = s2, s1
    m, n = len(s1), len(s2)
    prev = [0] * (n + 1)
    curr = [0] * (n + 1)
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i-1] == s2[j-1]:
                curr[j] = prev[j-1] + 1
            else:
                curr[j] = max(prev[j], curr[j-1])
        prev, curr = curr, prev
    return prev[n]

def lcs_bitparallel(s1, s2):
    m = len(s1)
    alphabet = set(s1) | set(s2)
    PM = {c: 0 for c in alphabet}
    for i, ch in enumerate(s1):
        PM[ch] |= (1 << i)
    M = 0
    for ch in s2:
        p = PM.get(ch, 0)
        u = M | p
        M = u | (u - (M & p) + M)
    return bin(M).count('1')

